# Unit tests of the fleet posture checks (MP.JAMF.1019 to MP.JAMF.1028), which read device inventory.
Describe 'Jamf Pro pack: fleet posture' {
    BeforeAll {
        . "$PSScriptRoot/Fixture.ps1"
        Import-JamfSpecMaester

        function New-FleetMobileDevice {
            <#
            One managed device in the shape GET /api/v2/mobile-devices/detail returns: the top level has
            mobileDeviceId and deviceType, the name is general.displayName, and the security section is null for
            an Apple TV or when LENIENT exception handling could not read it (-NoSecurity).
            #>
            param(
                [string] $Name = 'iPhone-01',
                [string] $DeviceType = 'iOS',
                [hashtable] $General = @{},
                [hashtable] $Security = @{},
                [switch] $NoSecurity
            )
            $g = @{ displayName = $Name; osVersion = '26.1'; managed = $true; supervised = $true; lastInventoryUpdateDate = [datetime]::UtcNow.AddDays(-1).ToString('o') }
            foreach ($k in $General.Keys) { $g[$k] = $General[$k] }
            $s = @{ passcodePresent = $true; passcodeCompliant = $true; passcodeCompliantWithProfile = $true; jailBreakDetected = $false; dataProtected = $true }
            foreach ($k in $Security.Keys) { $s[$k] = $Security[$k] }
            @{ mobileDeviceId = [guid]::NewGuid().ToString(); deviceType = $DeviceType; general = $g; security = $(if ($NoSecurity) { $null } else { $s }) }
        }

        function Invoke-FleetMacTest {
            param([string] $Id, [object[]] $Mac, [hashtable] $Parameter)
            $run = @{ Id = $Id; Cache = @{ (Get-JamfSpecQuery Computers) = @($Mac) } }
            if ($Parameter) { $run.Parameter = $Parameter }
            Invoke-JamfSpecTest @run
        }

        function Invoke-FleetMobileTest {
            param([string] $Id, [object[]] $Device, [hashtable] $Parameter)
            $run = @{ Id = $Id; Cache = @{ (Get-JamfSpecQuery MobileDevices) = @($Device) } }
            if ($Parameter) { $run.Parameter = $Parameter }
            Invoke-JamfSpecTest @run
        }
    }

    Context 'MP.JAMF.1019 FileVault recovery keys' {
        It 'passes when every encrypted Mac has a valid personal or an institutional key' {
            $macs = @(
                (New-JamfSpecMac -Name 'Personal')
                (New-JamfSpecMac -Name 'Institutional' -DiskEncryption @{ individualRecoveryKeyValidityStatus = 'NOT_APPLICABLE'; institutionalRecoveryKeyPresent = $true })
                (New-JamfSpecMac -Name 'Plain' -OperatingSystem @{ fileVault2Status = 'NOT_ENCRYPTED' } -DiskEncryption @{ individualRecoveryKeyValidityStatus = 'NOT_APPLICABLE' })
            )
            $row = Invoke-FleetMacTest -Id MP.JAMF.1019 -Mac $macs
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'All 2 Macs'
        }

        It 'fails when an encrypted Mac has an invalid or unknown key' {
            $macs = @(
                (New-JamfSpecMac)
                (New-JamfSpecMac -Name 'Invalid' -DiskEncryption @{ individualRecoveryKeyValidityStatus = 'INVALID' })
                (New-JamfSpecMac -Name 'Unknown' -OperatingSystem @{ fileVault2Status = 'BOOT_ENCRYPTED' } -DiskEncryption @{ individualRecoveryKeyValidityStatus = 'UNKNOWN' })
            )
            $row = Invoke-FleetMacTest -Id MP.JAMF.1019 -Mac $macs
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Invalid'
            $row.ResultDetail.TestResult | Should -Match 'Unknown'
        }

        It 'takes the share from the MinimumPercent parameter' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Invalid' -DiskEncryption @{ individualRecoveryKeyValidityStatus = 'INVALID' }))
            (Invoke-FleetMacTest -Id MP.JAMF.1019 -Mac $macs -Parameter @{ MinimumPercent = 50 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no Mac is encrypted' {
            $macs = @(New-JamfSpecMac -OperatingSystem @{ fileVault2Status = 'NOT_ENCRYPTED' })
            (Invoke-FleetMacTest -Id MP.JAMF.1019 -Mac $macs).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1020 System Integrity Protection' {
        It 'passes when SIP is on, leaving out Macs that did not report it' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'NoData' -Security @{ sipStatus = 'NOT_COLLECTED' }), (New-JamfSpecMac -Name 'NA' -Security @{ sipStatus = 'NOT_AVAILABLE' }))
            $row = Invoke-FleetMacTest -Id MP.JAMF.1020 -Mac $macs
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'All 1 Macs'
        }

        It 'fails when SIP is off on any Mac by default' {
            $macs = @(1..30 | ForEach-Object { New-JamfSpecMac -Name "Mac-$_" }) + (New-JamfSpecMac -Name 'Off' -Security @{ sipStatus = 'DISABLED' })
            $row = Invoke-FleetMacTest -Id MP.JAMF.1020 -Mac $macs
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match '\| Off \| DISABLED'
        }

        It 'is skipped when no Mac reports SIP' {
            (Invoke-FleetMacTest -Id MP.JAMF.1020 -Mac @(New-JamfSpecMac -Security @{ sipStatus = 'NOT_COLLECTED' })).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1021 Gatekeeper' {
        It 'passes with App Store or identified developers, leaving out Macs that did not report it' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Strict' -Security @{ gatekeeperStatus = 'APP_STORE' }), (New-JamfSpecMac -Name 'NoData' -Security @{ gatekeeperStatus = 'NOT_COLLECTED' }))
            $row = Invoke-FleetMacTest -Id MP.JAMF.1021 -Mac $macs
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'All 2 Macs'
        }

        It 'fails when Gatekeeper is off' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Off' -Security @{ gatekeeperStatus = 'DISABLED' }))
            (Invoke-FleetMacTest -Id MP.JAMF.1021 -Mac $macs).Result | Should -Be 'Failed'
        }

        It 'takes the share from the MinimumPercent parameter' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Off' -Security @{ gatekeeperStatus = 'DISABLED' }))
            (Invoke-FleetMacTest -Id MP.JAMF.1021 -Mac $macs -Parameter @{ MinimumPercent = 50 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no Mac reports Gatekeeper' {
            (Invoke-FleetMacTest -Id MP.JAMF.1021 -Mac @()).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1022 firewall' {
        It 'passes when enough Macs have the firewall on' {
            $macs = @(1..19 | ForEach-Object { New-JamfSpecMac -Name "Mac-$_" }) + (New-JamfSpecMac -Name 'Open' -Security @{ firewallEnabled = $false })
            $row = Invoke-FleetMacTest -Id MP.JAMF.1022 -Mac $macs
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'Open'
        }

        It 'fails below the minimum share' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Open' -Security @{ firewallEnabled = $false }))
            (Invoke-FleetMacTest -Id MP.JAMF.1022 -Mac $macs).Result | Should -Be 'Failed'
        }

        It 'is skipped when no Mac reports its firewall state' {
            (Invoke-FleetMacTest -Id MP.JAMF.1022 -Mac @(New-JamfSpecMac -Security @{ firewallEnabled = $null })).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1023 macOS version' {
        It 'passes when Macs run macOS 15 or later' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Sequoia' -OperatingSystem @{ version = '15.7.2' }), (New-JamfSpecMac -Name 'NoData' -OperatingSystem @{ version = $null }))
            $row = Invoke-FleetMacTest -Id MP.JAMF.1023 -Mac $macs
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'All 2 Macs'
        }

        It 'fails when a Mac runs an old macOS' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Ventura' -OperatingSystem @{ version = '13.6.1' }))
            $row = Invoke-FleetMacTest -Id MP.JAMF.1023 -Mac $macs
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Ventura'
        }

        It 'takes the oldest version from the MinimumMajorVersion parameter' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Sequoia' -OperatingSystem @{ version = '15.7.2' }))
            $row = Invoke-FleetMacTest -Id MP.JAMF.1023 -Mac $macs -Parameter @{ MinimumMajorVersion = 26 }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'macOS 26 or later'
        }

        It 'is skipped when no Mac reports a version' {
            (Invoke-FleetMacTest -Id MP.JAMF.1023 -Mac @(New-JamfSpecMac -OperatingSystem @{ version = '' })).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1024 check-in' {
        It 'passes when Macs contacted Jamf Pro recently' {
            (Invoke-FleetMacTest -Id MP.JAMF.1024 -Mac @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Mac-02'))).Result | Should -Be 'Passed'
        }

        It 'fails for a Mac that has not checked in, or never has' {
            $macs = @(
                (New-JamfSpecMac)
                (New-JamfSpecMac -Name 'Stale' -General @{ lastContact = [datetime]::UtcNow.AddDays(-45).ToString('o') })
                (New-JamfSpecMac -Name 'Never' -General @{ lastContact = $null })
            )
            $row = Invoke-FleetMacTest -Id MP.JAMF.1024 -Mac $macs
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Stale'
            $row.ResultDetail.TestResult | Should -Match '\| Never \| Never'
        }

        It 'takes the number of days from the MaximumDaysSinceContact parameter' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Stale' -General @{ lastContact = [datetime]::UtcNow.AddDays(-45).ToString('o') }))
            (Invoke-FleetMacTest -Id MP.JAMF.1024 -Mac $macs -Parameter @{ MaximumDaysSinceContact = 60 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no Mac is managed' {
            (Invoke-FleetMacTest -Id MP.JAMF.1024 -Mac @()).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1026 mobile passcode' {
        It 'passes when devices have a compliant passcode, falling back to passcodeCompliant' {
            $devices = @(
                (New-FleetMobileDevice)
                (New-FleetMobileDevice -Name 'NoProfile' -Security @{ passcodeCompliantWithProfile = $null; passcodeCompliant = $true })
                (New-FleetMobileDevice -Name 'TV' -DeviceType 'appleTv' -NoSecurity)
            )
            $row = Invoke-FleetMobileTest -Id MP.JAMF.1026 -Device $devices
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'All 2 mobile devices'
        }

        It 'fails for a device with no passcode or one that misses the profile' {
            $devices = @(
                (New-FleetMobileDevice)
                (New-FleetMobileDevice -Name 'NoPasscode' -Security @{ passcodePresent = $false; passcodeCompliant = $false; passcodeCompliantWithProfile = $false })
                (New-FleetMobileDevice -Name 'Weak' -Security @{ passcodeCompliantWithProfile = $false })
                (New-FleetMobileDevice -Name 'WeakNoProfile' -Security @{ passcodeCompliantWithProfile = $null; passcodeCompliant = $false })
            )
            $row = Invoke-FleetMobileTest -Id MP.JAMF.1026 -Device $devices
            $row.Result | Should -Be 'Failed'
            foreach ($name in 'NoPasscode', 'Weak', 'WeakNoProfile') { $row.ResultDetail.TestResult | Should -Match "\| $name \|" }
        }

        It 'takes the share from the MinimumPercent parameter' {
            $devices = @((New-FleetMobileDevice), (New-FleetMobileDevice -Name 'Weak' -Security @{ passcodeCompliantWithProfile = $false }))
            (Invoke-FleetMobileTest -Id MP.JAMF.1026 -Device $devices -Parameter @{ MinimumPercent = 50 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no device reports a passcode state' {
            (Invoke-FleetMobileTest -Id MP.JAMF.1026 -Device @(New-FleetMobileDevice -NoSecurity)).Result | Should -Be 'Skipped'
        }

        It 'reads the fixture of spec/Fixture.ps1 as well' {
            (Invoke-FleetMobileTest -Id MP.JAMF.1026 -Device @(New-JamfSpecMobileDevice)).Result | Should -Be 'Passed'
        }
    }

    Context 'MP.JAMF.1027 jailbreak' {
        It 'passes when no device is jailbroken' {
            $devices = @((New-FleetMobileDevice), (New-FleetMobileDevice -Name 'Unread' -NoSecurity))
            (Invoke-FleetMobileTest -Id MP.JAMF.1027 -Device $devices).Result | Should -Be 'Passed'
        }

        It 'fails when one device of many is jailbroken' {
            $devices = @(1..50 | ForEach-Object { New-FleetMobileDevice -Name "iPhone-$_" }) + (New-FleetMobileDevice -Name 'Broken' -Security @{ jailBreakDetected = $true })
            $row = Invoke-FleetMobileTest -Id MP.JAMF.1027 -Device $devices
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match '\| Broken \| Yes'
        }

        It 'takes the share from the MinimumPercent parameter' {
            $devices = @(1..50 | ForEach-Object { New-FleetMobileDevice -Name "iPhone-$_" }) + (New-FleetMobileDevice -Name 'Broken' -Security @{ jailBreakDetected = $true })
            (Invoke-FleetMobileTest -Id MP.JAMF.1027 -Device $devices -Parameter @{ MinimumPercent = 95 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no mobile device is managed' {
            (Invoke-FleetMobileTest -Id MP.JAMF.1027 -Device @()).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1028 iOS and iPadOS version' {
        It 'passes when iPhones and iPads run version 18 or later, leaving out other device types' {
            $devices = @(
                (New-FleetMobileDevice)
                (New-FleetMobileDevice -Name 'iPad-18' -General @{ osVersion = '18.7' })
                (New-FleetMobileDevice -Name 'TV' -DeviceType 'appleTv' -General @{ osVersion = '17.1' } -NoSecurity)
                (New-FleetMobileDevice -Name 'Watch' -DeviceType 'watch' -General @{ osVersion = '10.2' })
            )
            $row = Invoke-FleetMobileTest -Id MP.JAMF.1028 -Device $devices
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'All 2 iPhones and iPads'
        }

        It 'fails when a device runs an old version' {
            $devices = @((New-FleetMobileDevice), (New-FleetMobileDevice -Name 'Old' -General @{ osVersion = '16.7.10' }))
            $row = Invoke-FleetMobileTest -Id MP.JAMF.1028 -Device $devices
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'Old'
        }

        It 'takes the oldest version from the MinimumMajorVersion parameter' {
            $devices = @((New-FleetMobileDevice), (New-FleetMobileDevice -Name 'Old' -General @{ osVersion = '16.7.10' }))
            (Invoke-FleetMobileTest -Id MP.JAMF.1028 -Device $devices -Parameter @{ MinimumMajorVersion = 16 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no iPhone or iPad is managed' {
            (Invoke-FleetMobileTest -Id MP.JAMF.1028 -Device @(New-FleetMobileDevice -Name 'TV' -DeviceType 'appleTv' -NoSecurity)).Result | Should -Be 'Skipped'
        }
    }
}
